#!/usr/bin/env bash



# set -e: exit on errors
# set -x: verbose logging

set -ex



# Configure bash globbing for recursive cp command

shopt -s globstar



# Set variables

PORT="_build/SSB Reloaded (Dolphin)"
EXT=".png"



# Remove and recreate work directories

rm -drf "$PORT"
rm -drf "_temp"

mkdir -p "$PORT"
mkdir -p "_temp"



# Copy textures to work directories

cp -r "Ports/Dolphin/"* "$PORT"
cp **"/SMASH BROTHERS"*"$EXT" "_temp"



# Create directories

mkdir -p "$PORT/Background/Bonus/Board the Platforms"
mkdir -p "$PORT/Background/Bonus/Break the Targets"
mkdir -p "$PORT/Background/Bonus/Race to the Finish"
mkdir -p "$PORT/Background/Opening/Characters Running"
