mkdir -p "$PORT/Characters/Samus"
mkdir -p "$PORT/Characters/Yoshi"



# Copy, edit and rename textures

## extent (canvas size increase)

### (hd/(hd/sd)+x)*(hd/sd)
### hd = HD image width or height
### sd = SD image width or height
### hd/sd = Upscale ratio
### x = Canvas size extension (based on SD image size)

### w = Source image width
### h = Source image height

### option:distort:viewport = Stretch pixels at the edge
### \( +clone -flop \) -composite = Horizontal mirror extension
### \( +clone -flip \) -composite = Vertical mirror extension

## append and duplicate

### +duplicate: Duplicate input image once
### -duplicate: Duplicate input image x number of times

### +append: Add image(s) horizontally
### -append: Add image(s) vertically

magick "_temp/SMASH BROTHERS#043FDB22#0#3_all$EXT" -background none -extent "%[fx:int((w/(w/230)+2)*(w/230))]x%[fx:int(h)]" PNG32:"$PORT/Background/Bonus/Board the Platforms/tex1_232x4_a2bb6783d6db27b5_6$EXT"
